# The simulated 11-factor x 20-response study of Otava and Mylona (2020), generated by the
# supplement's own simulation chunk (seed 1234), unchanged.
source("data-raw/paper_supplement/supplement_code.R")
eval(parse(text = sim_src))
dss_sim <- list(
  coefs = matrices_to_coefs(mainEffects, quadraticEffects, interactions),
  seed = 1234L,
  generator = paste("Paper supplement simulation chunk (CaseStudiesFinal_vCodeSupplement.Rmd):",
                    "2-10 active factors per response, main N(0,5^2), quadratic p=0.2,",
                    "pairwise interactions p=0.3, effects rounded to 2 dp; factors 2, 6, 11 inflated x5.")
)
save(dss_sim, file = "data/dss_sim.rda", compress = "xz")
